WITH by_dimension AS (SELECT d.city, d.country, src.category, COUNT(*) AS num_rows, ROUND(SUM(src.price), 2) AS total_price, ROUND(AVG(src.cost), 2) AS avg_cost, GROUPING_ID() AS level_id FROM products src INNER JOIN suppliers d ON src.supplier_id = d.id GROUP BY GROUPING SETS ((d.city, d.country, src.category), (d.city))) SELECT country, num_rows, total_price, level_id FROM by_dimension ORDER BY country DESC;
